const { useState } = React;
const root = ReactDOM.createRoot(document.querySelector('#root'));

const Qty = () => {
  const [count, setCount] = useState(1);

  const addThree = () => {
    setCount((c) => c + 1);
    setCount((c) => c + 1);
    setCount((c) => c + 1);
  };

  return (
    <article className="card">
      <h3 className="card__title">오버사이즈 셔츠</h3>
      <div className="qty">
        <button className="qty__up" type="button" onClick={() => setCount((c) => c + 1)}>+1</button>
        <span className="qty__value">{count}개</span>
        <button className="qty__up3" type="button" onClick={addThree}>+3</button>
        <button className="qty__reset" type="button" onClick={() => setCount(1)}>초기화</button>
      </div>
    </article>
  );
};

root.render(<Qty />);
